parameters.jsCode:
const body = $json.body || $json;

const candidateId = body.candidateId || 'cand_demo_reject';
const candidateName = body.name || body.candidateName || 'Ứng viên';
const candidateEmail = body.email || body.candidateEmail || 'test.applicant@company.local';
const jobTitle = body.jobTitle || 'Chuyên viên Công nghệ';
const matchScore = Number(body.matchScore !== undefined ? body.matchScore : 45);
const requireHrApproval = body.requireHrApproval !== undefined ? Boolean(body.requireHrApproval) : false;

const parsed = typeof body.parsedSkillsJson === 'object' && body.parsedSkillsJson !== null ? body.parsedSkillsJson : {};
const rawSkills = (Array.isArray(parsed.coreSkills) && parsed.coreSkills.length > 0)
  ? [...parsed.coreSkills, ...(Array.isArray(parsed.secondarySkills) ? parsed.secondarySkills : [])]
  : (Array.isArray(parsed.skills) ? parsed.skills : (Array.isArray(body.parsedSkillsJson) ? body.parsedSkillsJson : (Array.isArray(body.skills) ? body.skills : [])));

const coreSkills = Array.isArray(parsed.coreSkills) && parsed.coreSkills.length > 0
  ? parsed.coreSkills
  : (rawSkills.length > 0 ? rawSkills.slice(0, 3) : ['Chuyên môn chung']);
const secondarySkills = Array.isArray(parsed.secondarySkills) ? parsed.secondarySkills : (rawSkills.length > 3 ? rawSkills.slice(3) : []);
const systemScaleScore = Number(parsed.systemScaleScore || body.systemScaleScore || 60);
const githubUrl = parsed.githubUrl || body.githubUrl || null;
const skills = rawSkills.length > 0 ? rawSkills : ['Kỹ năng chuyên môn'];
const skillsStr = Array.isArray(skills) ? skills.join(', ') : String(skills);
const companyName = body.companyName || 'Công ty Cổ phần Công nghệ HR Tech Hub';

const senderName = body.senderName || 'Bộ phận Thu hút & Phát triển Nhân tài';
const senderPhone = body.senderPhone || '0901 234 567';
const senderEmail = body.senderEmail || 'recruitment@company.com';

// Phân loại kịch bản (CV_SCREENING vs POST_INTERVIEW)
const stage = (body.stage || body.currentStage || 'CV_SCREENING').toUpperCase();
const isPostInterview = stage.includes('INTERVIEW') || stage.includes('PHỎNG VẤN') || stage.includes('VÒNG 2');
const scenarioCode = isPostInterview ? 'POST_INTERVIEW' : 'CV_SCREENING';

return [{
  json: {
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    matchScore,
    requireHrApproval,
    skills,
    coreSkills,
    secondarySkills,
    systemScaleScore,
    githubUrl,
    skillsStr,
    companyName,
    senderName,
    senderPhone,
    senderEmail,
    scenarioCode,
    isPostInterview
  }
}];

const data = $json;
const jobTitle = data.jobTitle || '';
const skillsStr = data.skillsStr || '';
const techContext = (jobTitle + ' ' + skillsStr).toLowerCase();

let careerAdvice;
let suggestedSkills;

if (techContext.includes('front') || techContext.includes('react') || techContext.includes('vue')) {
  careerAdvice = 'Đối với lộ trình phát triển Frontend chuyên sâu, bạn có thể tập trung nâng cao khả năng tối ưu hiệu năng hiển thị (LCP/FID), thiết kế component có tính tái sử dụng cao và bổ sung kiểm thử tự động (Unit/E2E test).';
  suggestedSkills = [
    'Tối ưu hóa Core Web Vitals & Web Performance',
    'Kiến trúc State Management quy mô lớn',
    'Automated Testing (Jest, Playwright) & CI/CD Frontend'
  ];
} else if (techContext.includes('devops') || techContext.includes('cloud') || techContext.includes('k8s')) {
  careerAdvice = 'Để chuẩn bị tốt cho các vị trí Cloud/DevOps quy mô lớn, chúng tôi đề xuất bạn củng cố kiến thức về Infrastructure as Code (Terraform), thiết kế hệ thống quan sát (Observability/Prometheus/Grafana) và bảo mật container.';
  suggestedSkills = [
    'Infrastructure as Code (Terraform, Ansible)',
    'Observability Stack (Prometheus, Grafana, OpenTelemetry)',
    'Kubernetes Security & Service Mesh (Istio)'
  ];
} else {
  careerAdvice = 'Để nâng cao tính cạnh tranh cho các vị trí Backend quy mô lớn, chúng tôi khuyến khích bạn tiếp tục hoàn thiện kiến trúc hệ thống phân tán, xử lý tải cao (High Concurrency) và thực hành xây dựng các dự án mẫu có tích hợp Cache và Message Queue.';
  suggestedSkills = [
    'Thiết kế Microservices & Domain-Driven Design (DDD)',
    'Tối ưu hóa Database (Indexing, Query Optimization)',
    'Distributed Caching (Redis) & Message Queue (Kafka/RabbitMQ)'
  ];
}

return [{
  json: {
    ...data,
    careerAdvice,
    suggestedSkills
  }
}];

const data = $json;
const matchScore = data.matchScore || 0;
const techContext = (data.jobTitle + ' ' + (data.skillsStr || '')).toLowerCase();

let talentPoolTag = 'TALENT_POOL_BACKEND';
if (techContext.includes('devops') || techContext.includes('cloud')) talentPoolTag = 'TALENT_POOL_DEVOPS';
else if (techContext.includes('data') || techContext.includes('ai')) talentPoolTag = 'TALENT_POOL_DATA_AI';
else if (techContext.includes('frontend') || techContext.includes('react')) talentPoolTag = 'TALENT_POOL_FRONTEND';

let candidateLevel = 'Junior';
if (data.systemScaleScore >= 80 || matchScore >= 75) candidateLevel = 'Senior';
else if (data.systemScaleScore >= 65 || matchScore >= 60) candidateLevel = 'Middle';

const detailedTalentTag = `${talentPoolTag}_${candidateLevel}_${matchScore >= 60 ? 'Priority' : 'General'}`;
const talentPoolTier = matchScore >= 70 ? 'PRIORITY_TALENT_POOL' : 'GENERAL_TALENT_POOL';

return [{
  json: {
    ...data,
    talentPoolTag,
    candidateLevel,
    detailedTalentTag,
    talentPoolTier
  }
}];

const data = $json;

const reEngage = new Date();
reEngage.setDate(reEngage.getDate() + 180);
const reEngagementDate = reEngage.toISOString().split('T')[0];
const reEngagementFormatted = reEngage.toLocaleDateString('vi-VN', {
  year: 'numeric',
  month: 'numeric',
  day: 'numeric'
});

return [{
  json: {
    ...data,
    reEngagementDate,
    reEngagementFormatted,
    reEngagementCycleDays: 180
  }
}];

const data = $json;
const candidateId = data.candidateId;

const cxSurveyUrl = `http://localhost:3001/recruitment/cx-feedback?candidateId=${candidateId}`;
const cxStars = [1, 2, 3, 4, 5].map(score => ({
  score,
  label: `${score} Sao`,
  url: `http://localhost:3001/recruitment/cx-feedback?candidateId=${candidateId}&score=${score}`
}));

return [{
  json: {
    ...data,
    cxSurveyUrl,
    cxStars
  }
}];

const body = $json.body || $json;

const candidateId = body.candidateId || 'cand_demo_reject';
const candidateName = body.name || body.candidateName || 'Ứng viên';
const candidateEmail = body.email || body.candidateEmail || 'test.applicant@company.local';
const jobTitle = body.jobTitle || 'Chuyên viên Công nghệ';
const matchScore = Number(body.matchScore !== undefined ? body.matchScore : 45);
const requireHrApproval = body.requireHrApproval !== undefined ? Boolean(body.requireHrApproval) : false;

// Extract rich skills & tech ATS metadata
const parsed = typeof body.parsedSkillsJson === 'object' && body.parsedSkillsJson !== null ? body.parsedSkillsJson : {};
const rawSkills = (Array.isArray(parsed.coreSkills) && parsed.coreSkills.length > 0)
  ? [...parsed.coreSkills, ...(Array.isArray(parsed.secondarySkills) ? parsed.secondarySkills : [])]
  : (Array.isArray(parsed.skills) ? parsed.skills : (Array.isArray(body.parsedSkillsJson) ? body.parsedSkillsJson : (Array.isArray(body.skills) ? body.skills : [])));

const coreSkills = Array.isArray(parsed.coreSkills) && parsed.coreSkills.length > 0
  ? parsed.coreSkills
  : (rawSkills.length > 0 ? rawSkills.slice(0, 3) : ['Chuyên môn chung']);
const secondarySkills = Array.isArray(parsed.secondarySkills) ? parsed.secondarySkills : (rawSkills.length > 3 ? rawSkills.slice(3) : []);
const systemScaleScore = Number(parsed.systemScaleScore || body.systemScaleScore || 60);
const githubUrl = parsed.githubUrl || body.githubUrl || null;

const skills = rawSkills.length > 0 ? rawSkills : ['Kỹ năng chuyên môn'];
const skillsStr = Array.isArray(skills) ? skills.join(', ') : String(skills);
const companyName = body.companyName || 'Công ty Cổ phần Công nghệ HR Tech Hub';

const senderName = body.senderName || 'Bộ phận Thu hút & Phát triển Nhân tài';
const senderPhone = body.senderPhone || '0901 234 567';
const senderEmail = body.senderEmail || 'recruitment@company.com';

// 1. Phân loại chuyên môn cho Talent Pool (Domain-Specific Categorization with Tie-breaking)
const techContext = (jobTitle + ' ' + skillsStr).toLowerCase();

const domainKeywords = {
  TALENT_POOL_DEVOPS: ['devops', 'cloud', 'docker', 'kubernetes', 'k8s', 'ci/cd', 'aws', 'terraform', 'linux', 'helm', 'sre', 'ansible', 'prometheus', 'grafana'],
  TALENT_POOL_DATA_AI: ['data', 'ai', 'machine learning', 'deep learning', 'nlp', 'spark', 'pandas', 'pytorch', 'tensorflow', 'llm', 'computer vision', 'mlops', 'data engineer'],
  TALENT_POOL_FRONTEND: ['frontend', 'react', 'vue', 'angular', 'ui', 'ux', 'next.js', 'css', 'html', 'tailwind', 'redux', 'javascript', 'typescript frontend', 'flutter'],
  TALENT_POOL_BACKEND: ['backend', 'node', 'nestjs', 'java', 'golang', 'python', 'postgres', 'postgresql', 'mysql', 'sql', 'redis', 'api', 'microservice', 'kafka', 'rabbitmq', 'c#', '.net', 'spring']
};

const domainScores = {
  TALENT_POOL_DEVOPS: 0,
  TALENT_POOL_DATA_AI: 0,
  TALENT_POOL_FRONTEND: 0,
  TALENT_POOL_BACKEND: 0
};

for (const [domain, keywords] of Object.entries(domainKeywords)) {
  for (const kw of keywords) {
    if (techContext.includes(kw)) {
      domainScores[domain]++;
    }
  }
}

let maxScore = 0;
let bestDomains = [];
for (const [domain, sc] of Object.entries(domainScores)) {
  if (sc > maxScore) {
    maxScore = sc;
    bestDomains = [domain];
  } else if (sc === maxScore && sc > 0) {
    bestDomains.push(domain);
  }
}

let talentPoolTag = 'TALENT_POOL_GENERAL';
let tieBreakRuleApplied = null;

if (maxScore === 0) {
  // Không xác định được kỹ năng công nghệ chuyên sâu
  talentPoolTag = 'TALENT_POOL_GENERAL';
  tieBreakRuleApplied = 'NO_TECH_KEYWORDS_DETECTED';
} else if (bestDomains.length === 1) {
  talentPoolTag = bestDomains[0];
  tieBreakRuleApplied = 'CLEAR_DOMAIN_WINNER';
} else {
  // TIE-BREAK RULE CHO ỨNG VIÊN ĐA NĂNG (FULLSTACK):
  // 1. Kiểm tra ưu tiên trực tiếp trong Job Title
  const jobLower = jobTitle.toLowerCase();
  if (jobLower.includes('frontend') && bestDomains.includes('TALENT_POOL_FRONTEND')) {
    talentPoolTag = 'TALENT_POOL_FRONTEND';
    tieBreakRuleApplied = 'TIE_BREAK_JOB_TITLE_FRONTEND';
  } else if (jobLower.includes('backend') && bestDomains.includes('TALENT_POOL_BACKEND')) {
    talentPoolTag = 'TALENT_POOL_BACKEND';
    tieBreakRuleApplied = 'TIE_BREAK_JOB_TITLE_BACKEND';
  } else if (jobLower.includes('devops') && bestDomains.includes('TALENT_POOL_DEVOPS')) {
    talentPoolTag = 'TALENT_POOL_DEVOPS';
    tieBreakRuleApplied = 'TIE_BREAK_JOB_TITLE_DEVOPS';
  } else if (jobLower.includes('data') && bestDomains.includes('TALENT_POOL_DATA_AI')) {
    talentPoolTag = 'TALENT_POOL_DATA_AI';
    tieBreakRuleApplied = 'TIE_BREAK_JOB_TITLE_DATA_AI';
  } else {
    // 2. Fullstack chuẩn doanh nghiệp: Backend là nền tảng xử lý logic và kiến trúc dữ liệu cốt lõi (Core System Scale)
    if (bestDomains.includes('TALENT_POOL_BACKEND')) {
      talentPoolTag = 'TALENT_POOL_BACKEND';
      tieBreakRuleApplied = 'TIE_BREAK_FULLSTACK_DEFAULT_TO_BACKEND_CORE_ARCHITECTURE';
    } else {
      talentPoolTag = bestDomains[0];
      tieBreakRuleApplied = 'TIE_BREAK_FIRST_MAX_DOMAIN';
    }
  }
}

// 2. Xây dựng Constructive Career Advice (Góp ý kỹ năng chuyên môn mang tính xây dựng)
let careerAdvice = '';
let suggestedSkills = [];

if (talentPoolTag === 'TALENT_POOL_BACKEND') {
  suggestedSkills = ['Thiết kế Microservices & Domain-Driven Design (DDD)', 'Tối ưu hóa Database (Indexing, Query Optimization)', 'Distributed Caching (Redis) & Message Queue (Kafka/RabbitMQ)'];
  careerAdvice = 'Để nâng cao tính cạnh tranh cho các vị trí Backend quy mô lớn, chúng tôi khuyến khích bạn tiếp tục hoàn thiện kiến trúc hệ thống phân tán, xử lý tải cao (High Concurrency) và thực hành xây dựng các dự án mẫu có tích hợp Cache và Message Queue.';
} else if (talentPoolTag === 'TALENT_POOL_FRONTEND') {
  suggestedSkills = ['Tối ưu hóa Core Web Vitals & Web Performance', 'Kiến trúc State Management quy mô lớn', 'Automated Testing (Jest, Playwright) & CI/CD Frontend'];
  careerAdvice = 'Đối với lộ trình phát triển Frontend chuyên sâu, bạn có thể tập trung nâng cao khả năng tối ưu hiệu năng hiển thị (LCP/FID), thiết kế component có tính tái sử dụng cao và bổ sung kiểm thử tự động (Unit/E2E test).';
} else if (talentPoolTag === 'TALENT_POOL_DEVOPS') {
  suggestedSkills = ['Kubernetes Orchestration & Helm', 'Infrastructure as Code (Terraform)', 'Observability & Monitoring (Prometheus/Grafana)'];
  careerAdvice = 'Để tiến xa hơn trong mảng DevOps/SRE, việc làm chủ quy trình GitOps, tự động hóa hạ tầng bằng Terraform và thiết lập hệ thống giám sát thời gian thực sẽ là lợi thế cạnh tranh vượt trội.';
} else if (talentPoolTag === 'TALENT_POOL_DATA_AI') {
  suggestedSkills = ['Triển khai Model lên Production (MLOps)', 'Xử lý dữ liệu lớn (Spark/Kafka)', 'Fine-tuning & RAG với Large Language Models'];
  careerAdvice = 'Với lĩnh vực Data/AI, các dự án triển khai thực tế trên môi trường Production (MLOps) và kỹ năng kết nối dữ liệu quy mô lớn sẽ giúp hồ sơ của bạn nổi bật hơn nữa trong các vòng tuyển dụng tới.';
} else {
  suggestedSkills = ['Xây dựng Portfolio dự án thực chiến trên GitHub', 'Làm quen với các công nghệ Cloud căn bản', 'Rèn luyện giải thuật & System Design cơ bản'];
  careerAdvice = 'Chúng tôi khuyến khích bạn tiếp tục xây dựng các dự án mẫu hoàn chỉnh trên GitHub để minh chứng trực quan năng lực công nghệ và phương pháp giải quyết vấn đề.';
}

// Khối HTML góp ý chuyên môn
const adviceHtmlBlock = `
  <div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-left: 4px solid #2563eb; border-radius: 6px; padding: 16px 18px; margin: 20px 0;">
    <h4 style="margin: 0 0 8px 0; font-size: 14px; color: #1e293b;">💡 Góc nhìn chuyên môn từ Ban Tuyển dụng Kỹ thuật:</h4>
    <p style="margin: 0 0 10px 0; font-size: 13px; color: #475569; line-height: 1.5;">${careerAdvice}</p>
    <p style="margin: 0 0 6px 0; font-size: 12px; font-weight: 600; color: #334155;">Gợi ý công nghệ & kỹ năng trọng tâm:</p>
    <ul style="margin: 0; padding-left: 18px; font-size: 12px; color: #64748b; line-height: 1.6;">
      ${suggestedSkills.map(s => `<li>${s}</li>`).join('')}
    </ul>
  </div>
`;

// 3. Phân loại kịch bản từ chối
let scenarioCode = (body.rejectionType || body.stage || '').toUpperCase();
if (!scenarioCode) {
  if (matchScore >= 70) {
    scenarioCode = 'TOP_TALENT';
  } else if (matchScore >= 50) {
    scenarioCode = 'POST_INTERVIEW';
  } else {
    scenarioCode = 'CV_SCREENING';
  }
}

let emailSubject = '';
let emailHtml = '';
let scenarioTitle = '';
let talentPoolTier = '';
let summaryForBackend = '';

const archivedAt = new Date().toISOString();

// === ENTERPRISE TALENT POOL RETENTION & RE-ENGAGEMENT TIMELINE ===
const reEngagementDate = new Date(Date.now() + 180 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
const expY = parseInt(body.experienceYears, 10) || 1;
const candidateLevel = expY >= 5 ? 'Senior' : (expY >= 2 ? 'Mid' : 'Junior');
const detailedTalentTag = `${talentPoolTag}_${candidateLevel}_${expY}YoE`;

const cxSurveyBlock = `
  <div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 14px; margin: 24px 0 16px 0; text-align: center; font-size: 13px; color: #475569;">
    <p style="margin: 0 0 8px 0; font-weight: 600;">Bạn đánh giá trải nghiệm ứng tuyển cùng chúng tôi như thế nào?</p>
    <div style="font-size: 18px; letter-spacing: 4px;">
      <a href="http://localhost:3001/recruitment/cx-feedback?candidateId=${candidateId}&score=5" style="text-decoration: none;" title="Rất hài lòng">⭐⭐⭐⭐⭐</a>
    </div>
    <p style="margin: 6px 0 0 0; font-size: 11px; color: #94a3b8;">Đánh giá của bạn giúp chúng tôi liên tục cải thiện quy trình tuyển dụng ngày một tốt hơn.</p>
  </div>
`;


if (scenarioCode === 'CV_SCREENING') {
  scenarioTitle = 'Từ chối vòng duyệt hồ sơ (Screening)';
  talentPoolTier = 'GENERAL_TALENT_POOL';
  emailSubject = `Thư phản hồi hồ sơ ứng tuyển vị trí ${jobTitle} – ${companyName}`;

  const paragraphs = `
    <p style="font-size: 15px; color: #334155; margin-bottom: 16px;">
      Chúng tôi thuộc bộ phận nhân sự thuộc công ty <strong>${companyName}</strong> nhận được hồ sơ ứng tuyển của bạn. Rất cám ơn vì sự quan tâm của bạn đối với vị trí việc làm <strong>${jobTitle}</strong>.
    </p>
    <p style="font-size: 15px; color: #334155; margin-bottom: 16px;">
      Tuy nhiên, sau khi xem xét các hồ sơ, chúng tôi nhận thấy định hướng hiện tại của vị trí cần ưu tiên ứng viên có kinh nghiệm chuyên sâu hơn ở một số mảng kỹ thuật cụ thể.
    </p>
    ${adviceHtmlBlock}
    <p style="font-size: 15px; color: #334155; margin-bottom: 24px;">
      Hồ sơ của bạn đã được lưu trữ an toàn trong hệ thống <strong>${talentPoolTag}</strong> của chúng tôi. Chúc bạn may mắn trong quá trình tìm việc và hi vọng sẽ có cơ hội được hợp tác với bạn trong tương lai.
    </p>
  `;

  emailHtml = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="font-family: Arial, 'Segoe UI', Helvetica, sans-serif; background-color: #f8fafc; margin: 0; padding: 24px; color: #1e293b; line-height: 1.6;">
  <div style="max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.06);">
    <div style="background: linear-gradient(135deg, #334155 0%, #475569 100%); height: 8px; width: 100%;"></div>
    <div style="padding: 32px 28px;">
      <p style="margin-top: 0; font-size: 15px; font-weight: 600; color: #0f172a;">Thân gửi ${candidateName},</p>
      ${paragraphs}
      ${cxSurveyBlock}
      <div style="font-size: 14px; color: #475569; border-top: 1px solid #e2e8f0; padding-top: 20px; line-height: 1.5;">
        <p style="margin: 0 0 6px 0;">Trân trọng,</p>
        <p style="margin: 0; font-weight: 700; color: #0f172a;">${senderName}</p>
        <p style="margin: 0; color: #0f172a; font-weight: 600;">${companyName}</p>
      </div>
    </div>
  </div>
</body>
</html>`;

  summaryForBackend = `[TỪ CHỐI VÒNG HỒ SƠ]: Đã gửi thư từ chối lịch thiệp & góp ý chuyên môn cho ứng viên ${candidateName}. Lưu vào Talent Pool (${talentPoolTag} - ${talentPoolTier}).`;

} else if (scenarioCode === 'POST_INTERVIEW') {
  scenarioTitle = 'Từ chối sau vòng phỏng vấn/bài test & Lưu hồ sơ';
  talentPoolTier = 'RETAINED_TALENT_POOL';
  emailSubject = `Thư phản hồi kết quả phỏng vấn vị trí ${jobTitle} – ${companyName}`;

  const paragraphs = `
    <p style="font-size: 15px; color: #334155; margin-bottom: 16px;">
      Một lần nữa cám ơn bạn đã tham gia buổi phỏng vấn cho vị trí việc làm <strong>${jobTitle}</strong> tại <strong>${companyName}</strong>. Với sự cố gắng và nhiệt tình của bạn cùng với những sẻ chia và cam kết sẽ đóng góp của bạn đã được chúng tôi đánh giá rất cao trong buổi phỏng vấn này. Song, sau khi xem xét và bàn bạc lại, chúng tôi chỉ quyết định lựa chọn một số ứng viên có mức độ tương thích cao hơn về kiến trúc hệ thống để tiếp tục đồng hành.
